import { Sprite, SpriteMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const texture = ctx.textureLoader.load(config.imageUrl, (tex) => {
    // no-op, texture is cached
  });

  const material = new SpriteMaterial({
    map: texture,
    transparent: true,
    depthWrite: false,
    sizeAttenuation: true,
  });

  const sprite = new Sprite(material);
  sprite.position.set(0, 1, 0.06);
  sprite.scale.set(1, 1, 1);
  sprite.name = 'pricing-card-2-label';

  sprite.userData.cleanup = () => {
    material.dispose();
    texture.dispose();
  };

  // No handlers, no primitives, no text overlay (baked into atlas)
  sprite.userData.handlers = {};

  return sprite;
}
